const originalText=new WeakMap(),originalAttr=new WeakMap();
function english(text){let out=text;const pairs=Object.entries(UI);if(typeof LANG!=='undefined')for(const [en,ko]of Object.entries(LANG))pairs.push([ko,en]);if(window.ATLAS_DATA)for(const c of ATLAS_DATA.countries)pairs.push([c.name,c.english]);pairs.sort((a,b)=>b[0].length-a[0].length);for(const [ko,en]of pairs)out=out.split(ko).join(en);return out.replace(/([\d,.]+)명/g,'$1 people').replace(/([\d,.—]+)건/g,'$1 projects').replace(/([\d,.]+)개/g,'$1').replace(/([\d]+)년/g,'$1').replace(/조 US\$/g,' trillion US$').replace(/억 US\$/g,' ×100 million US$');}
function applyLanguage(){document.documentElement.lang=atlasLanguage;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement.closest('script,style,[data-no-translate],.language-switch'))continue;const rec=originalText.get(n);const source=rec&&n.nodeValue===rec.last?rec.source:n.nodeValue;const next=atlasLanguage==='en'?english(source):source;if(n.nodeValue!==next)n.nodeValue=next;originalText.set(n,{source,last:next});}document.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const a of ['placeholder','aria-label']){if(!el.hasAttribute(a))continue;let rec=originalAttr.get(el)||{};const old=rec[a];const source=old&&el.getAttribute(a)===old.last?old.source:el.getAttribute(a);const next=atlasLanguage==='en'?english(source):source;if(el.getAttribute(a)!==next)el.setAttribute(a,next);rec[a]={source,last:next};originalAttr.set(el,rec);}});document.querySelectorAll('a[href]').forEach(a=>{const h=a.getAttribute('href');if(!h||/^(https?:|mailto:|#)/.test(h)||!h.includes('.html'))return;const [base,hash]=h.split('#'),[path,query]=base.split('?'),qs=new URLSearchParams(query||'');qs.set('lang',atlasLanguage);a.setAttribute('href',path+'?'+qs.toString()+(hash?'#'+hash:''));});document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===atlasLanguage)));}
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{atlasLanguage=b.dataset.lang;try{localStorage.setItem('atlas-language',atlasLanguage);localStorage.setItem('3trillion-language',atlasLanguage);}catch{}if(window.renderMethods)renderMethods();applyLanguage();});let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{applyLanguage();pending=false;});}).observe(document.body,{childList:true,subtree:true,characterData:true});applyLanguage();});
